"""Positive evidence for currency receipts and skin-unlock continuation."""
import base64
from functools import lru_cache
import cv2
import numpy as np

@lru_cache(maxsize=32)
def _glyph(encoded, height):
    raw = cv2.imdecode(np.frombuffer(base64.b64decode(encoded), np.uint8), 0)
    return cv2.resize(raw, (max(2, round(raw.shape[1]*height/720)),
                            max(2, round(raw.shape[0]*height/720))))

def _find(frame, encoded, bounds, white=True):
    h, w = frame.shape[:2]
    x1, y1, x2, y2 = bounds
    left, top = round(w*x1), round(h*y1)
    crop = frame[top:round(h*y2), left:round(w*x2)]
    if not crop.size:
        return None
    image = (np.all(crop > 205, axis=2).astype(np.uint8)*255 if white
             else cv2.cvtColor(crop, cv2.COLOR_RGB2GRAY))
    glyph = _glyph(encoded, h)
    if any(image.shape[i] < glyph.shape[i] for i in (0, 1)):
        return None
    _, score, _, loc = cv2.minMaxLoc(cv2.matchTemplate(image, glyph, cv2.TM_CCOEFF_NORMED))
    if score < .9:
        return None
    return left + loc[0] + glyph.shape[1]/2, top + loc[1] + glyph.shape[0]/2

def _valid(frame):
    return isinstance(frame, np.ndarray) and frame.ndim == 3 and frame.shape[2] == 3

def bling_receipt(frame):
    if not _valid(frame):
        return False
    h, w = frame.shape[:2]
    # Both title and rainbow token must be on a full-screen purple/cyan receipt.
    margin = frame[round(h*.25):round(h*.9), :round(w*.12)].astype(np.float32)
    backdrop = (margin[:,:,2] > margin[:,:,0]*1.25) & (margin[:,:,2] > margin[:,:,1]*1.05)
    if not backdrop.size or backdrop.mean() < .8:
        return False
    return (_find(frame, BLING_TITLE, (.35,.08,.65,.25)) is not None and
            _find(frame, BLING_TOKEN, (.4,.4,.65,.75), white=False) is not None)

def skin_receipt_continue_position(frame):
    if not _valid(frame):
        return None
    if (_find(frame, CURRENT_SKIN, (.55,0,.8,.1)) is None or
            _find(frame, REMAINING, (.65,.9,.95,1)) is None):
        return None
    position = _find(frame, CONTINUE, (.46,.8,.69,.92))
    if position is None:
        return None
    h, w = frame.shape[:2]
    button = frame[round(h*.825):round(h*.89), round(w*.49):round(w*.665)]
    blue = (button[:,:,0] < 85) & (button[:,:,1] > 65) & (button[:,:,2] > 170)
    return position if blue.size and blue.mean() > .35 else None

BLING_TITLE = ''
BLING_TOKEN = ''
CURRENT_SKIN = ''
REMAINING = ''
CONTINUE = ''
